/**
 * The eval runner.
 *
 * Runs a set of cases through one or more configurations and returns a report
 * that can be summarised without rerunning anything. The important properties
 * are that it never repeats work whose inputs are unchanged, and that it can
 * run entirely from cache with no provider at all, which is what lets the
 * README table be regenerated by anyone who checks out the repository.
 */
import { estimateCostUsd } from '../providers/pricing.js';
import type { LLMProvider } from '../providers/types.js';
import { generateBaseline } from '../generation/baseline.js';
import { generateWithAgent } from '../generation/agent.js';
import type { GenerationMode, GenerationResult } from '@nlam/shared';
import { judgeCase } from './checks.js';
import type { OutcomeCache} from './cache.js';
import { cacheKey, configurationFor } from './cache.js';
import type {
  CaseOutcome,
  ConfigurationSummary,
  EvalCase,
  RunConfiguration,
  RunReport,
} from './types.js';

export interface ProgressEvent {
  configuration: RunConfiguration;
  evalCase: EvalCase;
  index: number;
  total: number;
  source: 'cache' | 'provider';
  outcome: CaseOutcome;
}

export interface RunnerOptions {
  cases: readonly EvalCase[];
  modes: readonly GenerationMode[];
  cache: OutcomeCache;
  /** Omitted for an offline run, which then answers only from cache. */
  provider?: LLMProvider;
  /** Identity used for cache keys when running offline. */
  providerName?: string;
  modelName?: string;
  maxIterations?: number;
  timeBudgetMs?: number;
  /** Ignore cached outcomes and call the provider for every case. */
  fresh?: boolean;
  onProgress?: (event: ProgressEvent) => void;
  now?: () => number;
}

export class MissingOutcomeError extends Error {
  constructor(
    readonly caseId: string,
    readonly mode: GenerationMode,
  ) {
    super(
      `No cached outcome for case "${caseId}" in ${mode} mode, and no provider was supplied to produce one.`,
    );
    this.name = 'MissingOutcomeError';
  }
}

export async function runEval(options: RunnerOptions): Promise<RunReport> {
  const now = options.now ?? (() => Date.now());
  const startedAt = new Date(now()).toISOString();

  const providerName = options.provider?.name ?? options.providerName ?? 'gemini';
  const modelName = options.provider?.model ?? options.modelName ?? 'gemini-2.5-flash';

  const maxIterations = options.maxIterations ?? 12;

  let cacheHits = 0;
  let providerCalls = 0;

  const configurations: RunReport['configurations'] = [];

  for (const mode of options.modes) {
    const configuration = configurationFor(providerName, modelName, mode, maxIterations);
    const outcomes: CaseOutcome[] = [];

    let index = 0;
    for (const evalCase of options.cases) {
      index += 1;
      const key = cacheKey(evalCase.id, evalCase.description, configuration);

      let outcome = options.fresh ? undefined : await options.cache.get(key);
      let source: 'cache' | 'provider' = 'cache';

      if (outcome) {
        cacheHits += 1;
      } else {
        if (!options.provider) throw new MissingOutcomeError(evalCase.id, mode);

        const result = await runOne(options.provider, evalCase, mode, options);
        providerCalls += result.iterations;
        outcome = toOutcome(evalCase, mode, result);
        source = 'provider';
        await options.cache.set(key, outcome);
      }

      outcomes.push(outcome);
      options.onProgress?.({
        configuration,
        evalCase,
        index,
        total: options.cases.length,
        source,
        outcome,
      });
    }

    configurations.push({ configuration, outcomes, summary: summarise(outcomes, modelName) });
  }

  return {
    startedAt,
    finishedAt: new Date(now()).toISOString(),
    configurations,
    cacheHits,
    providerCalls,
  };
}

async function runOne(
  provider: LLMProvider,
  evalCase: EvalCase,
  mode: GenerationMode,
  options: RunnerOptions,
): Promise<GenerationResult> {
  if (mode === 'agent') {
    return generateWithAgent({
      description: evalCase.description,
      provider,
      maxIterations: options.maxIterations ?? 12,
      timeBudgetMs: options.timeBudgetMs ?? 120_000,
    });
  }
  return generateBaseline({
    description: evalCase.description,
    provider,
    timeBudgetMs: options.timeBudgetMs ?? 120_000,
  });
}

function toOutcome(
  evalCase: EvalCase,
  mode: GenerationMode,
  result: GenerationResult,
): CaseOutcome {
  const verdict = judgeCase(evalCase, result.applicationModel);

  return {
    caseId: evalCase.id,
    band: evalCase.band,
    mode,
    ok: result.ok,
    validFirstTry: result.validFirstTry,
    iterations: result.iterations,
    latencyMs: result.latencyMs,
    inputTokens: result.usage.inputTokens,
    outputTokens: result.usage.outputTokens,
    failureReason: result.failure?.reason ?? null,
    expectationsMet: verdict.expectationsMet,
    expectationFailures: verdict.expectationFailures,
    forbiddenMatches: verdict.forbiddenMatches,
    result,
  };
}

/* -------------------------------------------------------------------------- */
/* Summary                                                                    */
/* -------------------------------------------------------------------------- */

export function summarise(
  outcomes: readonly CaseOutcome[],
  modelName: string,
): ConfigurationSummary {
  const cases = outcomes.length;
  const rate = (count: number) => (cases === 0 ? 0 : round(count / cases, 4));

  const judged = outcomes.filter((outcome) => outcome.expectationsMet !== null);
  const injection = outcomes.filter((outcome) => outcome.band === 'adversarial');

  const inputTokens = outcomes.reduce((total, outcome) => total + outcome.inputTokens, 0);
  const outputTokens = outcomes.reduce((total, outcome) => total + outcome.outputTokens, 0);

  const failuresByReason: Record<string, number> = {};
  for (const outcome of outcomes) {
    if (!outcome.failureReason) continue;
    failuresByReason[outcome.failureReason] = (failuresByReason[outcome.failureReason] ?? 0) + 1;
  }

  const byBand: ConfigurationSummary['byBand'] = {};
  for (const outcome of outcomes) {
    const bucket = (byBand[outcome.band] ??= { cases: 0, validFinalRate: 0 });
    bucket.cases += 1;
    if (outcome.ok) bucket.validFinalRate += 1;
  }
  for (const bucket of Object.values(byBand)) {
    bucket.validFinalRate = round(bucket.validFinalRate / bucket.cases, 4);
  }

  return {
    cases,
    validFirstTryRate: rate(outcomes.filter((outcome) => outcome.validFirstTry).length),
    validFinalRate: rate(outcomes.filter((outcome) => outcome.ok).length),
    expectationsMetRate:
      judged.length === 0
        ? null
        : round(judged.filter((outcome) => outcome.expectationsMet).length / judged.length, 4),
    injectionResistedRate:
      injection.length === 0
        ? null
        : round(
            injection.filter((outcome) => outcome.forbiddenMatches.length === 0).length /
              injection.length,
            4,
          ),
    meanIterations:
      cases === 0
        ? 0
        : round(outcomes.reduce((total, outcome) => total + outcome.iterations, 0) / cases, 2),
    latencyMsP50: percentile(
      outcomes.map((outcome) => outcome.latencyMs),
      50,
    ),
    latencyMsP95: percentile(
      outcomes.map((outcome) => outcome.latencyMs),
      95,
    ),
    inputTokens,
    outputTokens,
    estimatedCostUsd: estimateCostUsd(modelName, { inputTokens, outputTokens }),
    failuresByReason,
    byBand,
  };
}

function percentile(values: readonly number[], p: number): number | null {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const rank = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
  return Math.round(sorted[rank] as number);
}

function round(value: number, places: number): number {
  const factor = 10 ** places;
  return Math.round(value * factor) / factor;
}
